test('technical no-op freezes both original confirmed archives at the atomic write boundary',async t=>{
 const f=await technicalNoopFixture(t),db=globalThis.__localReviewDB,original=db.batch,k='native_preparation_handoff_v1:'+ID,before=f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(k).value;db.batch=async statements=>{f.sql.prepare("UPDATE app_state SET value=json_set(value,'$.archive.status','finalized') WHERE key=?").run('site_archive_v1:'+f.a.qa.project_archive_id);return original(statements)};
 try{await assert.rejects(()=>api.progressNativePreparationHandoff(ID,f.body,{trusted_owner_service:true}),/并发|变化/)}finally{db.batch=original}assert.equal(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(k).value,before);assert.equal(f.sql.prepare("SELECT count(*) n FROM production_reviews WHERE decision='native_preparation_handoff_event' AND json_extract(note,'$.event')='technical-noop'").get().n,0);
});

test('a saved neutral marker never suppresses a new target, changed confirmed archive, or owner decision',async t=>{
 const f=await technicalNoopFixture(t);await api.progressNativePreparationHandoff(ID,f.body,{trusted_owner_service:true});const k='native_preparation_handoff_v1:'+ID,good=f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(k).value;let s=JSON.parse(good);s.checkpoint.technical_noop.render_target.caption_layout_sha256='0'.repeat(64);f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(s),k);assert.equal((await api.listWaitingNativePreparationHandoffs())[0].technical_noop_current,false);assert.equal((await api.nextWork()).kind,'native-preparation-handoff');f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(good,k);
 const ak='site_archive_v1:'+f.a.site_archive_id,old=f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(ak).value;f.sql.prepare("UPDATE app_state SET value=json_set(value,'$.archive.status','finalized') WHERE key=?").run(ak);assert.equal((await api.listWaitingNativePreparationHandoffs())[0].technical_noop_current,false);f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(old,ak);
 await api.decideMilestone(ID,f.m.id,f.m.revision,f.m.artifact_hash,f.m.mode_epoch,'revise',{reason:'SYNTHETIC actual later owner direction'},OWNER);assert.ok((await api.listWaitingNativePreparationHandoffs()).every(x=>x.technical_noop_current!==true));assert.equal(latest(await api.getJob(ID)).status,'revise');
});


test('legacy MiniCPM resumes only the current exact owner-requested rejected base while isolated task stays excluded',async t=>{const f=await fixture(t,'auto'),r=await returned(f),m=latest(r.job),j=await api.decideMilestone(ID,m.id,m.revision,m.artifact_hash,m.mode_epoch,'revise',{reason:'SYNTHETIC authorized current visual correction'},OWNER),legacy={...j,id:'job_9ef39025-d92e-4770-82d0-05881451c5df',owner_id:OWNER};assert.equal(authorizedLegacyPrivateRework(legacy),true);assert.ok(nativePreparationBinding(legacy));assert.equal(authorizedLegacyPrivateRework({...legacy,owner_id:undefined}),true,'public projection can identify only this exact receipt-backed candidate');assert.equal(nativePreparationBinding({...legacy,owner_id:undefined}),null,'authoritative binding still requires database owner');assert.equal(authorizedLegacyPrivateRework({...legacy,owner_id:'SYNTHETIC-wrong-owner'}),false);assert.equal(authorizedLegacyPrivateRework({...legacy,reviews:legacy.reviews.filter(r=>r.decision!=='media_rework_requested')}),false);const changed=structuredClone(legacy);changed.milestones.find(x=>x.id===m.id).artifact_hash='9'.repeat(64);assert.equal(authorizedLegacyPrivateRework(changed),false);assert.equal(nativePreparationBinding(changed),null);const missingFeedback={...legacy,reviews:legacy.reviews.filter(r=>r.decision!=='revise')};assert.equal(authorizedLegacyPrivateRework(missingFeedback),false);assert.equal(nativePreparationBinding(missingFeedback),null);const isolated={...legacy,id:'job_bf4b0b5a-3adc-4bb7-8560-25f20c3eeaee'};assert.equal(authorizedLegacyPrivateRework(isolated),false);assert.equal(nativePreparationBinding(isolated),null);});

