 const retry=await api.claimNativePreparationHandoff(ID,{queue_id:q.queue_id,version:next.native_preparation.handoff.version,executor:'finite-local-private-review-v1',invocation_id:'private-review-22222222-2222-4222-8222-222222222222',reason:'SYNTHETIC original complete audio retained after exact subtitle fix'},actor);await api.progressNativePreparationHandoff(ID,{queue_id:q.queue_id,version:retry.handoff.version,invocation_id:retry.handoff.invocation_id,lease_token:retry.lease_token,status:'blocked',artifacts:[],missing:[{code:'local-production:PRIVATE_PRODUCER_RESULT_UNKNOWN',detail:'ordinary-audio-and-editable-project'}],note:'SYNTHETIC known start guard before any new media'},actor);assert.equal((await api.nextWork()).kind,'native-preparation-handoff','exact prior caption failure allows byte-checked technical recovery from its start guard');
 const key='native_preparation_handoff_v1:'+ID,state=JSON.parse(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(key).value);state.version+=2;state.missing=[{code:'local-production:PRIVATE_PRODUCER_RESULT_UNKNOWN',detail:'ordinary-audio-and-editable-project'}];f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(state),key);assert.equal(await api.nextNativePreparationHandoff([],true),null);
